import{_ as e,o as t,c as n,a2 as r}from"./chunks/framework.RycU2wFZ.js";const c=JSON.parse('{"title":"学习地图","description":"从 Agent 基础到 Agent 支付，再到 AgentPay：理解自主 AI Agent 如何安全地花钱","frontmatter":{"title":"学习地图","description":"从 Agent 基础到 Agent 支付，再到 AgentPay：理解自主 AI Agent 如何安全地花钱"},"headers":[],"relativePath":"zh/learn/index.md","filePath":"zh/learn/index.md","lastUpdated":1792490239000}'),o={name:"zh/learn/index.md"};function i(s,a,l,h,d,p){return t(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="学习地图" tabindex="-1">学习地图 <a class="header-anchor" href="#学习地图" aria-label="Permalink to &quot;学习地图&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">实验性项目</p><p>AgentPay 目前处于实验阶段，<strong>尚未经过独立安全审计，请勿用于生产环境的真实资金</strong>。建议仅使用测试网和测试代币。</p></div><p>Agent 正在从&quot;回答问题&quot;变成&quot;执行任务&quot;：调用 API、购买数据、使用算力，甚至雇佣其他 Agent。当 Agent 开始花钱，一个新问题随之出现：</p><blockquote><p><strong>在没有人逐笔确认的情况下，Agent 在什么条件下才有资格花钱？</strong></p></blockquote><p>这个学习区先讲清楚问题的背景，再讲 AgentPay 是怎么回答它的。你不需要有区块链或支付领域的基础。</p><h2 id="一句话认识-agentpay" tabindex="-1">一句话认识 AgentPay <a class="header-anchor" href="#一句话认识-agentpay" aria-label="Permalink to &quot;一句话认识 AgentPay&quot;">​</a></h2><p><strong>LLM 可以提议付款，但不能批准付款。</strong></p><p>AgentPay 是放在 Agent 与真实资金之间的一层独立控制：单笔上限、滚动预算、白名单、频率熔断、失败恢复与审计，全部由确定性代码执行，而不是交给模型判断。</p><p>它与 x402 协议的分工是：</p><table tabindex="0"><thead><tr><th></th><th>回答的问题</th></tr></thead><tbody><tr><td><strong>x402</strong></td><td>怎么付？</td></tr><tr><td><strong>AgentPay</strong></td><td>该不该付？付多少？失败了怎么办？</td></tr></tbody></table><h2 id="我该从哪里开始" tabindex="-1">我该从哪里开始？ <a class="header-anchor" href="#我该从哪里开始" aria-label="Permalink to &quot;我该从哪里开始？&quot;">​</a></h2><h3 id="🚀-想先看效果-10-分钟体验" tabindex="-1">🚀 想先看效果：10 分钟体验 <a class="header-anchor" href="#🚀-想先看效果-10-分钟体验" aria-label="Permalink to &quot;🚀 想先看效果：10 分钟体验&quot;">​</a></h3><p>跑通三个场景：<strong>正常付款成功 → 超额被拒绝 → 失控循环被熔断</strong>。</p><p>→ <a href="./05-hands-on/ten-minute-demo">10 分钟 Demo</a></p><h3 id="按你的角色选择学习路径" tabindex="-1">按你的角色选择学习路径 <a class="header-anchor" href="#按你的角色选择学习路径" aria-label="Permalink to &quot;按你的角色选择学习路径&quot;">​</a></h3><h4 id="我是-agent-开发者-买方" tabindex="-1">我是 Agent 开发者（买方） <a class="header-anchor" href="#我是-agent-开发者-买方" aria-label="Permalink to &quot;我是 Agent 开发者（买方）&quot;">​</a></h4><p>我想让自己的 Agent 能安全地调用付费 API。</p><ol><li><a href="./01-agent-basics/agent-failure-modes">Agent 的常见失控方式</a></li><li><a href="./04-agentpay-concepts/financial-firewall">为什么需要金融防火墙</a></li><li><a href="./04-agentpay-concepts/budget-reservation">预算预留：为什么不能&quot;先检查后支付&quot;</a></li><li><a href="./04-agentpay-concepts/timeout-is-not-failure">超时不等于失败</a></li><li><a href="./05-hands-on/ten-minute-demo">10 分钟 Demo</a></li></ol><h4 id="我是-api-提供方-卖方" tabindex="-1">我是 API 提供方（卖方） <a class="header-anchor" href="#我是-api-提供方-卖方" aria-label="Permalink to &quot;我是 API 提供方（卖方）&quot;">​</a></h4><p>我想把自己的 API 变成按次收费的接口。</p><ol><li><a href="./02-agent-payments/http-402-and-x402">HTTP 402 与 x402</a></li><li><a href="./04-agentpay-concepts/payment-lifecycle">一次支付的完整生命周期</a></li><li><a href="./05-hands-on/first-paid-route">在控制台配置第一个付费路由</a></li><li><a href="./05-hands-on/draft-publish-rollback">草稿、发布与回滚</a></li></ol><h4 id="我是企业管理员" tabindex="-1">我是企业管理员 <a class="header-anchor" href="#我是企业管理员" aria-label="Permalink to &quot;我是企业管理员&quot;">​</a></h4><p>我要管理多个 Agent，并对花出去的每一笔钱负责。</p><ol><li><a href="./03-infra-map/agent-stack">Agent 基础设施全景</a></li><li><a href="./04-agentpay-concepts/multi-tenant">租户、项目、Agent 与 API Key</a></li><li><a href="./04-agentpay-concepts/dual-rail">虚拟钱包与链上支付：双轨架构</a></li><li><a href="./04-agentpay-concepts/agent-identity">Agent 身份：观测与自报</a></li><li><a href="./05-hands-on/audit-timeline">用审计时间线排查问题</a></li></ol><h2 id="全部内容" tabindex="-1">全部内容 <a class="header-anchor" href="#全部内容" aria-label="Permalink to &quot;全部内容&quot;">​</a></h2><p>学习区按&quot;由大到小&quot;组织：先了解 Agent 和 Agent 支付的通用知识，再看 AgentPay 在整套基础设施中的位置，最后深入概念和动手实践。</p><h3 id="第-1-章-agent-开发基础" tabindex="-1">第 1 章：Agent 开发基础 <a class="header-anchor" href="#第-1-章-agent-开发基础" aria-label="Permalink to &quot;第 1 章：Agent 开发基础&quot;">​</a></h3><p>不涉及 AgentPay 的通用知识，帮助你理解 Agent 为什么需要&quot;财务边界&quot;。</p><p><a href="./01-agent-basics/what-is-an-agent">什么是 Agent</a> · <a href="./01-agent-basics/tool-calling">工具调用</a> · <a href="./01-agent-basics/mcp">MCP</a> · <a href="./01-agent-basics/agent-frameworks">Agent 框架</a> · <a href="./01-agent-basics/agent-failure-modes">常见失控方式</a> · <a href="./01-agent-basics/autonomy-levels">自主度分级</a></p><h3 id="第-2-章-agent-支付" tabindex="-1">第 2 章：Agent 支付 <a class="header-anchor" href="#第-2-章-agent-支付" aria-label="Permalink to &quot;第 2 章：Agent 支付&quot;">​</a></h3><p>Agent 为什么要花钱、现有支付方式有什么局限、x402 和稳定币解决了什么。</p><p><a href="./02-agent-payments/why-agents-pay">为什么 Agent 需要花钱</a> · <a href="./02-agent-payments/payment-options">支付方式对比</a> · <a href="./02-agent-payments/http-402-and-x402">HTTP 402 与 x402</a> · <a href="./02-agent-payments/stablecoins-and-usdc">稳定币与 USDC</a> · <a href="./02-agent-payments/gasless-eip-3009">免 Gas 授权</a> · <a href="./02-agent-payments/micropayment-economics">微支付的成本</a> · <a href="./02-agent-payments/trust-problems">五个信任问题</a> · <a href="./02-agent-payments/ecosystem-landscape">生态概览</a></p><h3 id="第-3-章-基础设施全景" tabindex="-1">第 3 章：基础设施全景 <a class="header-anchor" href="#第-3-章-基础设施全景" aria-label="Permalink to &quot;第 3 章：基础设施全景&quot;">​</a></h3><p>把前两章的知识串起来，看 AgentPay 在整套 Agent 基础设施中处于哪一层、不做什么。</p><p><a href="./03-infra-map/agent-stack">Agent 技术栈分层</a> · <a href="./03-infra-map/where-agentpay-fits">AgentPay 的位置</a> · <a href="./03-infra-map/agentpay-vs-x402">AgentPay 与 x402</a></p><h3 id="第-4-章-agentpay-核心概念" tabindex="-1">第 4 章：AgentPay 核心概念 <a class="header-anchor" href="#第-4-章-agentpay-核心概念" aria-label="Permalink to &quot;第 4 章：AgentPay 核心概念&quot;">​</a></h3><p>设计背后的&quot;为什么&quot;，每篇都从一个具体的故障场景讲起。</p><p><a href="./04-agentpay-concepts/financial-firewall">金融防火墙</a> · <a href="./04-agentpay-concepts/payment-lifecycle">支付生命周期</a> · <a href="./04-agentpay-concepts/timeout-is-not-failure">超时不等于失败</a> · <a href="./04-agentpay-concepts/three-state-model">三态模型</a> · <a href="./04-agentpay-concepts/budget-reservation">预算预留</a> · <a href="./04-agentpay-concepts/dual-rail">双轨支付</a> · <a href="./04-agentpay-concepts/agent-identity">Agent 身份</a> · <a href="./04-agentpay-concepts/idempotency">幂等与免费重放</a> · <a href="./04-agentpay-concepts/multi-tenant">多租户</a> · <a href="./04-agentpay-concepts/threat-model-lite">通俗版威胁模型</a></p><h3 id="第-5-章-动手实践" tabindex="-1">第 5 章：动手实践 <a class="header-anchor" href="#第-5-章-动手实践" aria-label="Permalink to &quot;第 5 章：动手实践&quot;">​</a></h3><p>基于 Python SDK、Go 网关与 Web 控制台的操作教程。</p><p><a href="./05-hands-on/ten-minute-demo">10 分钟 Demo</a> · <a href="./05-hands-on/first-paid-route">第一个付费路由</a> · <a href="./05-hands-on/policy-in-action">配置策略并观察拦截</a> · <a href="./05-hands-on/read-payment-trace">读懂支付链路</a> · <a href="./05-hands-on/audit-timeline">审计时间线</a> · <a href="./05-hands-on/draft-publish-rollback">草稿、发布与回滚</a></p><h3 id="第-6-章-速查资料" tabindex="-1">第 6 章：速查资料 <a class="header-anchor" href="#第-6-章-速查资料" aria-label="Permalink to &quot;第 6 章：速查资料&quot;">​</a></h3><p><a href="./06-resources/glossary">术语表</a> · <a href="./06-resources/id-prefixes">ID 前缀速查</a> · <a href="./06-resources/safety-redlines">安全红线</a> · <a href="./06-resources/faq">常见问题</a> · <a href="./06-resources/further-reading">延伸阅读</a></p><h2 id="learn、guide-与-specs-的区别" tabindex="-1">Learn、Guide 与 Specs 的区别 <a class="header-anchor" href="#learn、guide-与-specs-的区别" aria-label="Permalink to &quot;Learn、Guide 与 Specs 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>栏目</th><th>回答的问题</th><th>适合什么时候读</th></tr></thead><tbody><tr><td><strong>Learn</strong>（本区）</td><td>为什么这样设计？</td><td>想理解概念和思路</td></tr><tr><td><strong>Guide</strong></td><td>怎么做？</td><td>想动手部署和配置</td></tr><tr><td><strong>Specs</strong></td><td>精确的定义是什么？</td><td>想实现、集成或核对细节</td></tr></tbody></table><p>Learn 只讲思路，不重复规范内容。每篇概念页末尾都会给出对应 Specs 的链接，供你深入阅读。</p><h2 id="约定" tabindex="-1">约定 <a class="header-anchor" href="#约定" aria-label="Permalink to &quot;约定&quot;">​</a></h2><ul><li>金额统一以<strong>最小整数单位</strong>表示（USDC 为 6 位小数，<code>1 USDC = 1,000,000</code>），示例中不使用浮点数。</li><li>示例代码默认使用 <strong>Python SDK</strong>。</li><li>示例网络默认使用<strong>测试网</strong>（如 Arbitrum Sepolia）和测试代币。</li></ul>',48)])])}const f=e(o,[["render",i]]);export{c as __pageData,f as default};
